import { Activity, useEffect, useEffectEvent } from 'react';

function Chat({ roomId, theme }: Props) {
  const onConnected = useEffectEvent(() => notify('Connected', theme));
  useEffect(() => {
    const connection = connect(roomId, onConnected);
    return () => connection.close();
  }, [roomId]);

  return <Activity mode={roomId ? 'visible' : 'hidden'}><Messages /></Activity>;
}
